import json,re,os
D=os.path.expanduser('~/Projects/open-agreements/practice-guides/non-compete/us/')
F="consideration"
E=[
("alabama","yes","That is why Alabama treats continued employment of an existing employee as adequate consideration, while a payment cannot rescue a covenant that is void for a different reason.",None,"Stated in the Pitney Bowes discussion, not a dedicated consideration section."),
("arizona","yes","Arizona follows the majority rule that continued at-will employment is sufficient consideration to support a covenant, even one signed after employment has already begun.","consideration",""),
("arkansas","yes","\"An employee's continued employment is sufficient consideration for a covenant not to compete agreement.\"[^q6-aca-consideration]","consideration","Statutory rule."),
("delaware","yes","Delaware can treat continued at-will employment as sufficient consideration when signing is a condition of continued employment","consideration","Powell: signing as condition of keeping the position; adequacy still weighed in equities balancing."),
("florida","yes","Florida courts treat continued at-will employment as sufficient consideration, so an employee can be bound by a non-compete signed months or years after the hire date.","consideration",""),
("georgia","AMBIGUOUS","Georgia practitioners generally treat continued at-will employment as sufficient — but no modern GRCA-era appellate decision squarely settles the point, so treat it as an area to monitor","consideration","GRCA silent on consideration; practitioner view only, no modern appellate holding."),
("indiana","yes","In Indiana, an employer's promise to continue an at-will employee's job is valid consideration for a non-compete signed during employment","consideration","Med-1 Solutions v. Taylor (2024)."),
("iowa","yes","Iowa decisions treat continued employment for an indefinite period as sufficient consideration to support a covenant not to compete, even when the covenant is signed after employment begins","consideration","Guide says 'Generally yes'."),
("kansas","yes","Kansas does not treat continued employment of an existing at-will employee as inadequate consideration for a covenant signed after hire","consideration","Puritan-Bennett."),
("kentucky","no","No, not by itself, for an existing employee. Since *Charles T. Creech, Inc. v. Brown*, requiring a current employee to sign a non-compete without giving anything new","consideration","Creech: new consideration (raise, promotion, training) required."),
("mississippi","yes","Mississippi treats continued at-will employment as sufficient consideration to support a restrictive covenant","consideration","Caveat: covenant extracted just before bad-faith discharge is weaker."),
("missouri","AMBIGUOUS","This is unsettled. Missouri appellate cases have treated continued at-will employment plus access to the employer's customers or trade secrets as adequate consideration","consideration","JumboSack vs. Baker/Durrell split; state supreme court has not resolved for non-competes."),
("nevada","AMBIGUOUS","Historically, continued at-will employment was enough, but the modern statute adds a proportionality question.","consideration","Camco says yes at common law; unresolved whether continued employment alone satisfies NRS 613.195(1)(d)."),
("new-jersey","yes","adequate consideration for a post-employment restraint can be found in the original employment contract or in continued employment after the covenant is signed","consideration","Hogan; guide says 'Often, yes' (Hogan involved ~3 years of continued employment)."),
("new-mexico","no","Probably not by itself for an existing at-will employee.","consideration","Short quote; see extended check."),
("new-york","no","an employer's forbearance from discharging an at-will worker can supply consideration — but only if the employment then continues for a substantial period","consideration","Sufficient only if employment continues for a substantial period after signing (Zellner)."),
("north-carolina","no","a covenant imposed on an existing employee must be supported by *new* consideration — continued at-will employment is not enough","consideration","New consideration can be modest (e.g., $500)."),
("ohio","yes","Ohio holds that an employer's agreement to continue an at-will employment relationship is itself sufficient consideration for a non-compete an existing employee signs","consideration","Lake Land v. Columber."),
("oklahoma","AMBIGUOUS","Oklahoma has not squarely decided whether continued at-will employment, by itself, is sufficient consideration for a restrictive covenant signed mid-employment.","consideration","Unsettled per guide."),
("pennsylvania","no","When a covenant is added after employment has begun, it is enforceable only if the employee receives new and valuable consideration beyond merely keeping the job","consideration","Socko; UWOA recital does not cure."),
("tennessee","no","a covenant an existing employee signs is supported by consideration where the employee then remains employed for an appreciable period","consideration","Guide says 'Yes, when the employment actually continues' — sufficient only after an appreciable (unfixed) period of continued employment (Central Adjustment Bureau v. Ingram)."),
("texas","AMBIGUOUS","What is risky is relying on nothing more than continued at-will employment, because a promise the employer can revoke at any moment raises the illusory-promise problem the next question addresses.","consideration","Texas frames consideration as reasonably related to protectable interest (Marsh/Sheshunoff); guide does not give a yes/no on continued employment alone."),
("utah","yes","an offer of employment, including continued at-will employment, can be sufficient consideration for a non-compete, even when the employee signs after starting work","consideration",""),
("wisconsin","yes","an employer's forbearance in exercising its right to terminate an at-will employee is lawful consideration for signing a restrictive covenant","consideration","Runzheimer; forbearance must be genuine (no sign-then-fire)."),
("colorado","yes","an employer that forbears from terminating an existing at-will employee gives adequate consideration for a non-compete signed after employment begins","continued-employment-consideration","Statutory 14-day notice to current workers still required (procedural)."),
("connecticut","yes","The current Connecticut rule is that continued at-will employment can supply sufficient consideration for a restrictive covenant signed after employment has begun","continued-employment-consideration","Continued employment must be connected to the covenant (Schimenti); Dur-A-Flex."),
("maryland","yes","Maryland treats an employer's agreement to continue an at-will employee as sufficient consideration for a covenant signed after employment begins","continued-employment-consideration","Simko."),
("michigan","yes","\"Mere continuation of employment is sufficient consideration to support a noncompete agreement in an at-will employment setting.\"[^qis-continued-employment]","continued-employment-consideration","Only for genuine at-will employees; just-cause employees need separate consideration (QIS)."),
("south-carolina","no","When a covenant is signed after employment has already begun, South Carolina requires separate, independent consideration — continued at-will employment alone is not enough","continued-employment-consideration","Poole v. Incentives Unlimited."),
("montana","no","*Access Organics* held that simple continued employment did not supply good consideration for a non-compete signed more than four months after hiring","consideration-after-hire","Guide says 'Usually no'; independent consideration needed."),
("new-hampshire","yes","New Hampshire recognizes continued employment after signing as consideration for a covenant not to compete","consideration-after-hire","RSA 275:70 notice gate for new hires is separate."),
("illinois","no","Either two years of continued employment after signing, or other professional or financial benefits adequate to support the restraint.","adequate-consideration","Sufficient only after ~2 years of continued employment (Fifield, codified 820 ILCS 90/5)."),
("south-dakota","yes","SDCL 53-9-11 permits an employee to agree at the time of employment or during employment, while older case law treats continued employment as sufficient consideration in that setting","consideration-termination","Zakinski (older case); fired-without-fault employees get a reasonableness balancing."),
("vermont","yes","the Vermont Supreme Court held that continued at-will employment alone is sufficient consideration to support a non-compete entered into during the employment relationship","mid-employment-consideration","Summits 7 v. Kelly."),
("west-virginia","no","If employment began without a non-compete, a later covenant needs new, independent consideration; continued at-will employment alone is not enough under West Virginia law","mid-employment-consideration","Environmental Products."),
("washington","no","give independent consideration for any covenant signed after employment starts. Continued employment alone is not enough","disclosure-and-consideration","RCW 49.62.020; Labriola."),
("wyoming","no","Wyoming common law requires separate, contemporaneous consideration[^brown-post-hire-consideration] for the new promise — continued at-will employment, by itself, is not enough.","post-hire-consideration","Applies to covenants outside the 2025 statutory void (pre-2025 cohort and statutory exceptions)."),
("idaho","AMBIGUOUS","That means continued at-will employment can support an eighteen-month-or-shorter covenant, but it is not enough by itself for a longer restriction.","duration-limits","Depends on covenant length: sufficient for <=18-month restraint, not for longer (Idaho Code 44-2704)."),
("louisiana","yes","Continued at-will employment generally suffices, as in *Cellular One, Inc. v. Boyd*, where the covenant the court analyzed was signed as a condition of continued employment",None,"Civil-law 'lawful cause' framing."),
("massachusetts","no","the agreement must be supported by fair and reasonable consideration independent from continued employment, with at least 10 business days' notice before it takes effect",None,"MNAA (agreements on/after Oct 1, 2018) abrogated the older continued-employment rule."),
("minnesota","AMBIGUOUS","Minn. Stat. § 181.988 makes covered covenants not to compete void and unenforceable[^minn-181-988-voids-employment-noncompetes], unless a sale-of-business or dissolution exception applies.",None,"Near-total ban for agreements on/after July 1, 2023; pre-2023 Sanborn rule required independent consideration."),
("rhode-island","AMBIGUOUS","Rhode Island treats continued at-will employment, plus training and licensure support, as part of a lawful exchange that can support a restraint agreed mid-employment",None,"Walls: continued employment PLUS training; preliminary-injunction posture only, not a final holding on continued employment alone."),
("oregon","no","Continued employment alone is not a valid trigger. The covenant must be tied either to the original hire (with the two-week notice) or to a subsequent bona fide advancement.","timing-advancement","ORS 653.295(1)(a) statutory formation gateway."),
("california","AMBIGUOUS","California voids employee non-compete agreements by statute. Business and Professions Code section 16600 makes any contract that restrains someone from engaging in a lawful profession, trade, or business void to that extent",None,"State voids nearly all employee non-competes; consideration question moot."),
("north-dakota","AMBIGUOUS","North Dakota voids employee non-competes under N.D. Cent. Code § 9-08-06, one of the strictest bans in the United States, with only sale-of-goodwill and dissociation exceptions.",None,"State voids nearly all employee non-competes; consideration question moot."),
]
norm=lambda s:re.sub(r'\s+',' ',s)
out=[];bad=0
for st,lab,q,anc,note in E:
    t=norm(open(D+st+'.md').read())
    ok=norm(q) in t and 40<=len(q)<=400
    if not ok: bad+=1;print("BAD",st,len(q),norm(q) in t)
    if st=="new-mexico": pass
    out.append({"family":F,"state":st,"label":lab,"quote":q,"anchor":("{#"+anc+"}") if anc else None,"note":note})
json.dump(out,open('consideration.json','w'),indent=1,ensure_ascii=False)
print(len(out),sum(o['label']!='AMBIGUOUS' for o in out),sum(o['label']=='AMBIGUOUS' for o in out),bad)
